import{z as i,x as A,o as e,c as s,q as t,j as B,D as E,d as n,s as l,S as o}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"资本结构套利","description":"","frontmatter":{"title":"资本结构套利","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/capital-structure-arb.md","filePath":"quant/capital-structure-arb.md","lastUpdated":1791413859000}'),d={name:"quant/capital-structure-arb.md"};function p(u,a,D,c,h,C){const r=A("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="资本结构套利" tabindex="-1">资本结构套利 <a class="header-anchor" href="#资本结构套利" aria-label="Permalink to &quot;资本结构套利&quot;">​</a></h1><div class="epigraph"><p>同一家公司的股、债、CDS 与转债是对同一资产过程的不同要求权；相对价值若只存在于模型里，实盘赚到的往往是对冲误差与资本撤离。</p><footer>—— 结构映射见 Merton, Journal of Finance, 1974；策略度量见 Yu, Financial Analysts Journal, 2006</footer></div><p><a href="/quant/fi-relative-value">上一课</a>的 RV 发生在利率与信用曲线内部。资本结构套利的缺口是<strong>跨要求权</strong>：用 <a href="/quant/merton-structural">Merton 结构模型</a> 把股权波动映射到信用，再在 CDS、现金债、股票期权与 <a href="/quant/convertible-credit">可转债</a> 之间做相对价值。主干 <a href="/quant/convertible-arb">可转债套利</a>、<a href="/quant/cds-bond-basis">CDS–债券基差</a> 已写两条边。本课给地图：不是再推一遍看涨–看跌，而是问对冲后还剩什么、何时相关变成 1。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>结构模型说股权是资产看涨、债务是无风险债减看跌。若 CDS 隐含的资产波动与期权隐含波动不一致，理论上可买便宜的保护、卖贵的，或反过来。Yu（2006）的度量是：这种「错价」的收敛慢、回撤深，模型误设与跳跃违约会把纸面套利变成方向性信用。问题是把策略定义成<strong>对冲误差的风险预算</strong>，而不是「Merton 公式算出的免费午餐」。</p><p><span class="marginnote">术语翻译：资本结构套利就是「拿同一家公司的不同证券互相比价」。股、债、CDS 都从同一个资产价值里切出来的份额，好比同一块蛋糕按不同规则分成的几块，加起来该等于整块蛋糕——若市场把它们的价格切成互相矛盾的总数，就买便宜的、卖贵的，等切法恢复一致时收钱。</span></p><p>与纯固收 RV：资本结构腿引入股票跳与借券；与纯股票多空：信用腿引入违约与回收。两边的流动性时钟不同，危机里往往同时变差。</p><h3 id="对冲比率在跳时失效" tabindex="-1">对冲比率在跳时失效 <a class="header-anchor" href="#对冲比率在跳时失效" aria-label="Permalink to &quot;对冲比率在跳时失效&quot;">​</a></h3><p>连续路径下 delta、DV01、CS01 可以对齐。跳到违约时，股权与 CDS 的缺口不是局部导数能补的。短端利差在 Merton 原文里过低，用它给周频交易定对冲，会系统性卖空短端保护。强度模型与结构模型混用时，要写清哪一条腿在用哪一个核。</p><p><span class="marginnote">转债套利是资本结构套利的一个可交易子集：条款把凸性写死。没有转债条款、只拿 CDS 对股票，对冲误差通常更大。</span></p>',10)),(e(),B(o,null,{default:E(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E5%BB%BA%E4%BB%93%EF%BC%9A%E4%B9%B0%E7%8E%B0%E9%87%91%E5%80%BA%20%2B%20%E4%B9%B0%20CDS%20%E4%BF%9D%E6%8A%A4%22%5D%20--%3E%20NORM%5B%22%E5%B9%B3%E6%97%B6%EF%BC%9ADV01%20%E4%B8%8E%20CS01%20%E5%AF%B9%E9%BD%90%EF%BC%8C%E8%B5%9A%E5%9F%BA%E5%B7%AE%E6%94%B6%E6%95%9B%22%5D%0A%20%20NORM%20--%3E%20JUMP%5B%22%E5%85%AC%E5%8F%B8%E8%B7%B3%E5%88%B0%E8%BF%9D%E7%BA%A6%22%5D%0A%20%20JUMP%20--%3E%20BOND%5B%22%E5%80%BA%E5%88%B8%E8%85%BF%EF%BC%9A%E5%8F%AA%E6%94%B6%E5%9B%9E%E5%9B%9E%E6%94%B6%E7%8E%87%20R%22%5D%0A%20%20JUMP%20--%3E%20CDS%5B%22CDS%20%E8%85%BF%EF%BC%9A%E6%8B%8D%E5%8D%96%E5%90%8E%E8%B5%94%E4%BB%98%201-R%22%5D%0A%20%20BOND%20--%3E%20GAP%5B%22%E5%AF%B9%E5%86%B2%E8%AF%AF%E5%B7%AE%EF%BC%9A%E7%BB%93%E7%AE%97%E6%97%B6%E7%82%B9%E3%80%81%E5%8F%82%E7%85%A7%E5%80%BA%E5%8A%A1%E4%B8%8E%E8%B7%B3%E5%89%8D%E5%88%A9%E5%B7%AE%22%5D%0A%20%20CDS%20--%3E%20GAP%0A%20%20GAP%20--%3E%20LOSS%5B%22%E7%BA%B8%E9%9D%A2%E6%94%B6%E6%95%9B%E5%8F%98%E6%88%90%E6%96%B9%E5%90%91%E6%80%A7%E6%8D%9F%E7%9B%8A%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>用数字看这张图：回收率 \\(R=40\\%\\) 时，债券腿每 100 元面值收回 40 元、CDS 腿赔付 60 元，账面上正好互补；但赔付要等拍卖结算，跳前利差、参照债务选择与期间融资都会让「互补」出现缺口——这正是要把缺口当风险预算来管理的原因。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>宇宙：有流动 CDS 或转债、可借正股。信号：模型价差、基差、隐含–实现。对冲：股票 delta、指数 CDS、利率。限额：单名跳跃、行业信用、融资。回测必须用可成交的 CDS 惯例与债券融资，不能用结构模型的理论价当成交。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>同一 \\(V_t\\) 进入不同合约，摩擦与分段资本使价格暂时分叉。策略卖的是「分叉会收」，付的是分叉在去杠杆时扩大。Mitchell–Pedersen–Pulvino 的慢资本故事在转债上已经写过：同类账户同向时，便宜可以更便宜。</p><p><span class="marginnote">直觉类比：把公司资产想成一根水位柱。债是「水位跌破某一刻度就归债权人」的承诺，股是刻度之上的剩余水位。水位波动越大，跌破刻度的概率越高，信用保护就越值钱——结构模型做的事，就是把「波动率」翻译成「离刻度还有多远」。</span></p>',6)),(e(),B(o,null,{default:E(()=>[l(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20V%5B%22%E8%B5%84%E4%BA%A7%E4%BB%B7%E5%80%BC%E8%BF%87%E7%A8%8B%22%5D%20--%3E%20Eq%5B%22%E8%82%A1%E6%9D%83%E4%B8%8E%E6%9C%9F%E6%9D%83%22%5D%0A%20%20V%20--%3E%20Cr%5B%22%E5%80%BA%E4%B8%8E%20CDS%22%5D%0A%20%20V%20--%3E%20Cb%5B%22%E8%BD%AC%E5%80%BA%22%5D%0A%20%20Eq%20--%3E%20Spr%5B%22%E8%B7%A8%E8%A6%81%E6%B1%82%E6%9D%83%E4%BB%B7%E5%B7%AE%22%5D%0A%20%20Cr%20--%3E%20Spr%0A%20%20Cb%20--%3E%20Spr%0A%20%20Spr%20--%3E%20Hdg%5B%22%E5%AF%B9%E5%86%B2%E8%AF%AF%E5%B7%AE%E4%B8%8E%E8%B7%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何规避内幕或操纵信用事件。回收率、basket 违约相关、主权是另一套。评价不要用无融资的理论夏普。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>资本结构套利是跨股、债、CDS、转债的相对价值，锚来自结构或强度模型。</li><li>实盘对象是对冲误差与融资，不是 Merton 公式的残差为零。</li><li>跳与慢资本让均值回复可以断裂。</li><li>出处：Merton, <em>JF</em>, 1974；Yu, <em>FAJ</em>, 2006；转债腿见 Mitchell, Pedersen and Pulvino, <em>AER</em>, 2007。</li></ul>',4))])}const m=i(d,[["render",p]]);export{S as __pageData,m as default};
